import re,html
h=open('gh.html',encoding='utf-8',errors='ignore').read()
heads=[(m.group(1),m.start()) for m in re.finditer(r'<h2[^>]*\bid="([a-z_0-9]+)"', h)]
for i,(ev,st) in enumerate(heads):
    if ev not in {"check_run","check_suite","workflow_run"}: continue
    end=heads[i+1][1] if i+1<len(heads) else len(h)
    body=re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',h[st:end])))
    for s in re.split(r'(?<=\.)\s+', body):
        if 'automatically subscribed' in s or 'level access' in s:
            print(f"[{ev}] {s.strip()[:300]}")
    print()
